@import url("https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&display=swap");

.field,
.place-autocomplete {
  min-height: 60px;
  height: auto;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: flex-end;
}

.swap-field {
  min-height: 60px;
  height: auto;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}

.homepage {
  --page-bg: #f1f5fb;
  --surface: #ffffff;
  --surface-soft: #f6f9fe;
  --surface-border: #c9d7ea;
  --text: #193356;
  --text-soft: #597191;
  --primary: var(--theme-primary-strong, #b8141b);
  --primary-strong: #b8141b;
  --accent: var(--theme-primary, #dc1e26);
  --success: #234777;
  --danger: var(--theme-primary-strong, #b8141b);
  --shadow-xl: 0 28px 60px rgba(10, 28, 52, 0.2);
  --shadow-lg: 0 18px 38px rgba(10, 27, 48, 0.14);
  --shadow-md: 0 12px 24px rgba(10, 27, 48, 0.1);
  --heading-font: var(--app-font-family);
  --body-font: var(--app-font-family);

  min-height: 100vh;
  position: relative;
  color: var(--text);
  font-family: var(--body-font);
  isolation: isolate;
  overflow: hidden;
  background:
    radial-gradient(circle at 8% 10%, rgba(24, 72, 135, 0.16), transparent 28%),
    radial-gradient(circle at 92% 10%, rgba(56, 129, 224, 0.18), transparent 24%),
    radial-gradient(circle at 52% 92%, rgba(33, 72, 123, 0.14), transparent 34%),
    linear-gradient(180deg, #f6f9fe 0%, var(--page-bg) 46%, #f6f9fe 100%);
}

.homepage::before,
.homepage::after {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
}

.homepage::before,
.homepage::after {
  display: none !important;
}

.homepage *,
.homepage *::before,
.homepage *::after {
  box-sizing: border-box;
}

.homepage h1,
.homepage h2,
.homepage h3,
.homepage h4,
.homepage h5 {
  font-family: var(--heading-font);
}

/* ─── Hero ────────────────────────────────────────────────────────────────── */
.hero-section {
  position: relative;
  overflow: visible;
  isolation: isolate;
  min-height: calc(100svh - 70px);
  display: flex;
  align-items: center;
  padding: clamp(34px, 5vh, 58px) 20px 120px;
}

.hero-section::before {
  z-index: 1;
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 7% 12%, rgba(28, 86, 161, 0.19), transparent 34%),
    radial-gradient(circle at 88% 18%, rgba(53, 123, 214, 0.17), transparent 38%);
  pointer-events: none;
}

.hero-bg-image {
  z-index: 0;
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center center;
  opacity: 0;
  pointer-events: none;
}

.hero-overlay {
  z-index: 2;
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, rgba(15, 23, 42, 0.7) 0%, rgba(15, 23, 42, 0.3) 50%, transparent 85%);
}

.hero-content {
  position: relative;
  z-index: 3;
  width: min(100%, 1540px);
  max-width: 1540px;
  margin: 0 auto;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
  align-items: end;
}

.hero-copy-block {
  color: #f6f9fe;
  max-width: 1180px;
  padding: 2px 4px 8px;
  animation: fade-up 0.7s ease both;
}

.hero-kicker {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  min-height: 32px;
  padding: 0 14px;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  font-size: 9.9px;
  font-weight: 700;
  color: #f3f7fd;
  border: 1px solid rgba(235, 242, 253, 0.45);
  background: rgba(14, 36, 64, 0.52);
}

.hero-copy-block h1 {
  margin: 14px 0 0;
  font-size: clamp(27px, 3.96vw, 43.2px);
  line-height: 1.03;
  letter-spacing: -0.02em;
  color: rgba(255, 255, 255, 0.92);
  white-space: nowrap;
}

.hero-copy-block p {
  margin: 16px 0 0;
  max-width: 100%;
  color: rgba(222, 234, 251, 0.72);
  font-size: 13.5px;
  line-height: 1.5;
  white-space: nowrap;
}

.hero-metric-grid {
  margin-top: 24px;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 10px;
}

.hero-metric-card {
  border: 1px solid rgba(235, 243, 253, 0.24);
  border-radius: 14px;
  background: rgba(14, 33, 58, 0.34);
  padding: 10px;
  backdrop-filter: blur(6px);
}

.hero-metric-card strong {
  display: block;
  font-family: var(--heading-font);
  font-size: 16.2px;
  line-height: 1.05;
  letter-spacing: -0.01em;
  color: rgba(255, 255, 255, 0.86);
}

.hero-metric-card span {
  display: block;
  margin-top: 6px;
  color: rgba(191, 215, 247, 0.75);
  font-size: 9.9px;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  font-weight: 600;
}

.hero-tag-row {
  margin-top: 16px;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.hero-tag {
  border-radius: 999px;
  min-height: 28px;
  padding: 0 12px;
  font-size: 10.8px;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  color: rgba(246, 249, 254, 0.78);
  border: 1px solid rgba(240, 246, 253, 0.26);
  background: rgba(15, 37, 65, 0.28);
}

/* ─── Search panel ────────────────────────────────────────────────────────── */
.search-panel {
  position: center;
  border: 1px solid rgba(205, 222, 244, 0.82);
  border-radius: 20px;
  padding: 16px 18px 18px;
  box-shadow: var(--shadow-xl);
  backdrop-filter: blur(8px);
  background: linear-gradient(
    156deg,
    rgba(255, 255, 255, 0.82) 0%,
    rgba(246, 249, 254, 0.78) 52%,
    rgba(245, 248, 254, 0.74) 100%
  );
  animation: panel-in 0.8s ease 0.1s both;
  margin-bottom: -110px;
}

.search-panel::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background:
    radial-gradient(circle at 10% 8%, rgba(255, 255, 255, 0.34), transparent 42%),
    radial-gradient(circle at 96% 8%, rgba(28, 86, 161, 0.06), transparent 36%),
    radial-gradient(circle at 3% 92%, rgba(53, 123, 214, 0.05), transparent 34%);
  pointer-events: none;
}

.search-panel::after {
  content: "";
  position: absolute;
  top: 1px;
  left: 16px;
  right: 16px;
  height: 34%;
  border-radius: 20px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.85) 0%, rgba(255, 255, 255, 0) 100%);
  pointer-events: none;
}

.search-panel > * {
  position: relative;
  z-index: 1;
}

.search-panel > .booking-content {
  z-index: 3;
}

.search-panel > .search-btn {
  z-index: 2;
  margin: 14px auto 0;
}

/* ─── Tabs ────────────────────────────────────────────────────────────────── */
.tabs-wrap {
  display: flex;
  justify-content: center;
}

.tabs {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border-radius: 13px;
  padding: 5px;
  margin: 0 auto 14px;
  background: rgba(233, 241, 252, 0.8);
  border: 1px solid #c7d9f1;
}

.tab {
  border: 0;
  border-radius: 9px;
  min-height: 36px;
  min-width: 118px;
  padding: 0 13px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: transparent;
  color: #2c486c;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.25s ease;
}

.tab:hover {
  background: rgba(255, 255, 255, 0.85);
}

.tab.active {
  color: #ffffff;
  background: linear-gradient(135deg, var(--primary), var(--primary-strong));
  box-shadow: 0 10px 22px rgba(28, 86, 161, 0.34);
}

/* ── AIRBNB ANIMATED TABS WIDGET OVERRIDES ── */
.tabs.airbnb-tabs-wrap {
  position: relative !important;
  display: inline-flex !important;
  align-items: center !important;
  gap: 12px !important;
  padding: 0 !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

.tab.airbnb-widget-tab {
  position: relative !important;
  border-radius: 9999px !important;
  min-height: 38px !important;
  padding: 0 20px !important;
  font-size: 13.5px !important;
  font-weight: 600 !important;
  color: #475569 !important;
  background: transparent !important;
  box-shadow: none !important;
  transition: color 0.2s ease !important;
}

.tab.airbnb-widget-tab:hover {
  color: #0f172a !important;
  background: rgba(241, 245, 249, 0.85) !important;
}

.tab.airbnb-widget-tab.active {
  color: #e11d48 !important; /* Airbnb Active Red */
  font-weight: 700 !important;
  background: transparent !important;
  box-shadow: none !important;
}

.tab.airbnb-widget-tab.active .tab-icon-wrap {
  color: #e11d48 !important;
}

/* ─── Trip type chips ─────────────────────────────────────────────────────── */
.booking-content {
  margin-top: 4px;
  position: relative;
  z-index: 3;
}

.trip-switch {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  flex-wrap: wrap;
  margin-bottom: 12px;
  position: relative;
  z-index: 10;
}

.trip-chip {
  border: 1px solid #c1d6f2;
  border-radius: 999px;
  background: #f6f9fe;
  color: #31517b;
  min-height: 30px;
  padding: 0 13px;
  font-size: 10.4px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  cursor: pointer;
  transition: all 0.22s ease;
}

.trip-chip:hover {
  border-color: #96bae9;
}

.trip-chip.active {
  border-color: transparent;
  color: #ffffff;
  background: linear-gradient(135deg, #2064bd, #144484);
  box-shadow: 0 10px 18px rgba(25, 87, 169, 0.3);
}

/* Search grid
   2-row layout for the booking form:

   Row 1: [Source] [swap 44px] [Destination] [Departure] [Return]
   Row 2: supporting fields left-aligned, right side left open for search btn

   This prevents all 7 columns cramming into one row and ensures
   every field has adequate width and breathing room.
   ─────────────────────────────────────────────────────────────────────────── */
.search-grid {
  display: grid;
  align-items: end;
  gap: 14px;
}

.search-grid > .field,
.search-grid > .place-autocomplete,
.search-grid > .traveller-field,
.search-grid > .class-field,
.search-grid > .swap-field {
  align-self: end;
  min-width: 0;
}

/* ── Row 1: origin | swap | destination | departure | return
   ── Row 2: traveller | class (left-aligned, search btn floats right)
   Using named grid areas for clarity and easy responsive overrides        */
.standard-grid {
  display: grid;
  grid-template-rows: auto;
}
.standard-grid.two-way {
  grid-template-columns:
    minmax(190px, 1.08fr)
    48px
    minmax(190px, 1.08fr)
    minmax(205px, 0.9fr)
    minmax(205px, 0.9fr)
    minmax(240px, 1fr)
    minmax(160px, 0.72fr);
}
.standard-grid.one-way {
  grid-template-columns:
    minmax(190px, 1.08fr)
    48px
    minmax(190px, 1.08fr)
    minmax(205px, 0.9fr)
    minmax(240px, 1.15fr)
    minmax(160px, 0.85fr);
}

.standard-grid .source-field      { grid-column: 1; grid-row: 1; }
.standard-grid .swap-field        { grid-column: 2; grid-row: 1; }
.standard-grid .destination-field { grid-column: 3; grid-row: 1; }
.standard-grid .departure-field   { grid-column: 4; grid-row: 1; }

.standard-grid.two-way .return-field    { grid-column: 5; grid-row: 1; }
.standard-grid.two-way .traveller-field { grid-column: 6; grid-row: 1; }
.standard-grid.two-way .class-field     { grid-column: 7; grid-row: 1; }

.standard-grid.one-way .traveller-field { grid-column: 5; grid-row: 1; }
.standard-grid.one-way .class-field     { grid-column: 6; grid-row: 1; }

.standard-grid .departure-field,
.standard-grid .return-field {
  min-width: 0;
}

/* ── Bus grid: 2-row as well
   Row 1: origin | swap | destination
   Row 2: departure date | return date                                      */
.bus-standard-grid {
  display: grid;
  gap: 10px 12px;
  align-items: end;
}
.bus-standard-grid.two-way {
  grid-template-columns:
    minmax(170px, 1.12fr)
    40px
    minmax(170px, 1.12fr)
    minmax(150px, 0.86fr)
    minmax(150px, 0.86fr);
}
.bus-standard-grid.one-way {
  grid-template-columns:
    minmax(170px, 1.12fr)
    40px
    minmax(170px, 1.12fr)
    minmax(150px, 0.86fr);
}

.bus-standard-grid .source-field      { grid-column: 1; grid-row: 1; }
.bus-standard-grid .swap-field        { grid-column: 2; grid-row: 1; }
.bus-standard-grid .destination-field { grid-column: 3; grid-row: 1; }
.bus-standard-grid .departure-field   { grid-column: 4; grid-row: 1; }
.bus-standard-grid.two-way .return-field { grid-column: 5; grid-row: 1; }

/* ─── Multi-city ──────────────────────────────────────────────────────────── */
.multi-city-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.multi-city-row {
  display: grid;
  align-items: end;
  grid-template-columns:
    minmax(150px, 1fr) minmax(150px, 1fr) minmax(170px, 1fr) 98px;
  gap: 10px;
}

.multi-footer-row {
  display: grid;
  grid-template-columns: minmax(250px, 330px) minmax(180px, 240px);
  gap: 10px;
}

.multi-actions {
  display: flex;
  align-items: flex-end;
  gap: 8px;
  padding-bottom: 2px;
}

.action-circle {
  border: 1px solid var(--surface-border);
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: #ffffff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.2s ease;
  box-shadow: var(--shadow-md);
}

.action-add { color: #1f71dd; }
.action-add:hover { border-color: #9dc2f3; color: #16519e; }
.action-delete { color: var(--danger); }
.action-delete:hover:not(:disabled) { border-color: #b5cff1; background: #f6f9fd; }
.action-delete:disabled { cursor: not-allowed; opacity: 0.52; }

/* ─── Fields ──────────────────────────────────────────────────────────────── */
.field {
  min-width: 0;
  position: relative;
}

.class-field {
  position: relative;
  z-index: 10;
}

.class-field:focus-within {
  z-index: 1200;
}

.place-autocomplete {
  position: relative;
  z-index: 10;
}

.place-autocomplete:focus-within {
  z-index: 1200;
}

.field label {
  display: block;
  margin: 0 0 5px;
  color: var(--text-soft);
  font-size: 9.4px;
  font-weight: 700;
  letter-spacing: 0.095em;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.field-control {
  width: 100%;
  max-width: 100%;
  min-height: 44px;
  height: 44px;
  border: 1px solid var(--surface-border);
  border-radius: 10px;
  background: linear-gradient(180deg, #ffffff 0%, #f6f9fe 100%);
  color: var(--text);
  font-size: 12px;
  font-weight: 600;
  padding: 9px 12px;
  outline: none;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.88),
    0 7px 15px rgba(18, 42, 75, 0.08);
}

.place-input {
  padding-right: 12px;
}

.place-dropdown {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  right: 0;
  z-index: 1300;
  border-radius: 12px;
  border: 1px solid #edd4cb;
  background: #ffffff;
  box-shadow: 0 18px 30px rgba(13, 74, 83, 0.14);
  max-height: 220px;
  overflow-y: auto;
  padding: 6px;
}

.place-option {
  width: 100%;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: #1f2a44;
  min-height: 36px;
  text-align: left;
  padding: 0 10px;
  font-size: 11.7px;
  font-weight: 600;
  cursor: pointer;
}

.place-option:hover {
  background: #F3F4F6;
}

.place-meta {
  min-height: 34px;
  display: flex;
  align-items: center;
  color: #5d779a;
  font-size: 10.8px;
  padding: 0 10px;
}

.bus-place-dropdown {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  right: 0;
  z-index: 1300;
  border-radius: 12px;
  border: 1px solid #bbd1ee;
  background: #ffffff;
  box-shadow: 0 18px 30px rgba(17, 31, 49, 0.2);
  max-height: 250px;
  overflow-y: auto;
  padding: 6px;
}

.bus-place-option {
  display: block;
  width: 100%;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: #0b5093;
  min-height: 38px;
  text-align: left;
  padding: 8px 12px;
  font-size: 0.92rem;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}

.bus-place-option:hover {
  background: #edf4fc;
  color: #003875;
}

.bus-place-meta {
  min-height: 36px;
  display: flex;
  align-items: center;
  color: #5d779a;
  font-size: 0.85rem;
  padding: 0 12px;
}

.field-control:focus {
  border-color: #88b2e7;
  box-shadow: 0 0 0 4px rgba(28, 86, 161, 0.14);
}

.field.has-error .field-control {
  border-color: #dc2626;
  box-shadow: 0 0 0 4px rgba(220, 38, 38, 0.11);
}

select.field-control {
  appearance: none;
  background-image:
    linear-gradient(45deg, transparent 50%, #6c86a7 50%),
    linear-gradient(135deg, #6c86a7 50%, transparent 50%);
  background-position:
    calc(100% - 13px) calc(50% - 3px),
    calc(100% - 8px)  calc(50% - 3px);
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
  padding-right: 26px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

select.field-control option {
  background: #ffffff;
  color: #1f2a44;
}

.control-wrap {
  position: relative;
}

.control-wrap svg {
  position: absolute;
  top: 50%;
  left: 14px;
  transform: translateY(-50%);
  color: #6683a9;
  pointer-events: none;
  opacity: 1;
  z-index: 2;
}

.with-leading-icon {
  padding-left: 44px;
}

.field-with-icon {
  position: relative;
  z-index: 5;
}

.watermark-field {
  color: #92a8c4;
  background: #f6f9fe;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 11px;
}

.field-control.watermark-field:disabled {
  border-color: transparent;
  background: transparent;
  box-shadow: none;
  color: #9eb2cb;
  -webkit-text-fill-color: #9eb2cb;
  opacity: 1;
  cursor: default;
}

.standard-grid .watermark-field {
  padding-left: 14px;
  padding-right: 14px;
  font-size: 11.7px;
}

.watermark-field::placeholder {
  color: #9eb2cb;
}

/* ─── Swap button ─────────────────────────────────────────────────────────── */
.swap-field {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  padding-bottom: 1px;
}

.swap-btn {
  width: 38px;
  height: 44px;
  min-height: 44px;
  border-radius: 11px;
  border: 1px solid var(--surface-border);
  background: #ffffff;
  color: #2a61a8;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  box-shadow: var(--shadow-md);
  transition: all 0.2s ease;
}

.swap-btn:hover {
  transform: translateY(-1px);
  border-color: #9cc0f0;
  color: #144b93;
}

/* ─── Traveller field ─────────────────────────────────────────────────────── */
.traveller-field {
  position: relative;
}

.traveller-trigger {
  width: 100%;
  max-width: 100%;
  min-height: 44px;
  height: 44px;
  border: 1px solid var(--surface-border);
  border-radius: 12px;
  background: linear-gradient(180deg, #ffffff 0%, #f6f9fe 100%);
  color: var(--text);
  padding: 0 10px;
  font: inherit;
  text-align: left;
  appearance: none;
  outline: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  cursor: pointer;
  overflow: hidden;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.88),
    0 7px 15px rgba(18, 42, 75, 0.08);
}

.traveller-trigger.open,
.traveller-trigger:hover {
  border-color: #96bae8;
}

.traveller-trigger:focus-visible {
  outline: none;
  border-color: #88b2e7;
  box-shadow:
    0 0 0 4px rgba(28, 86, 161, 0.14),
    inset 0 1px 0 rgba(255, 255, 255, 0.88),
    0 7px 15px rgba(18, 42, 75, 0.08);
}

.traveller-summary {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  flex: 1;
  overflow: hidden;
  color: var(--text);
}

