/* ─── Marquee ─────────────────────────────────────────────────────────────── */
.marquee {
  position: relative;
  overflow-x: auto;
  overflow-y: hidden;
  cursor: grab;
  mask-image: linear-gradient(to right, transparent 0%, black 1.5%, black 98.5%, transparent 100%);
  scrollbar-width: none;
  -ms-overflow-style: none;
  scroll-behavior: auto;
  overscroll-behavior-x: contain;
  touch-action: pan-y;
}

.marquee::-webkit-scrollbar {
  display: none;
}

.marquee.is-dragging {
  cursor: grabbing;
  user-select: none;
}

.marquee-track {
  display: flex;
  width: max-content;
  transform: translateZ(0);
  will-change: scroll-position;
}

.marquee.is-dragging .marquee-slide {
  pointer-events: none;
}

.marquee-slide {
  flex: 0 0 auto;
  padding-right: 16px;
}

.offer-marquee .marquee-slide { width: 340px; }
.popular-routes-marquee .marquee-slide { width: 340px; }

