}
 
.home-ai-chat-message.assistant {
  align-self: flex-start;
  background: linear-gradient(180deg, #ffffff, #fff5f5);
  color: #3e1214;
  border: 1px solid rgba(220, 30, 38, 0.15);
}
 
.home-ai-chat-message.user {
  align-self: flex-end;
  background: linear-gradient(135deg, var(--primary, #dc1e26), var(--primary-strong, #b8141b));
  color: #ffffff;
}
 
.home-ai-chat-message.typing {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  width: 52px;
}
 
.home-ai-chat-message.typing span {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--primary, #dc1e26);
  animation: home-ai-typing 1s ease-in-out infinite;
}
 
.home-ai-chat-message.typing span:nth-child(2) { animation-delay: 0.15s; }
.home-ai-chat-message.typing span:nth-child(3) { animation-delay: 0.3s; }
 
.home-ai-chat-form {
  margin-top: 9px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
}
 
.home-ai-chat-form input {
  min-height: 35px;
  border: 1px solid rgba(220, 30, 38, 0.2);
  border-radius: 10px;
  padding: 0 10px;
  font-size: 10.8px;
  color: #3e1214;
  outline: none;
  background: #ffffff;
}
 
.home-ai-chat-form input:focus {
  border-color: var(--primary, #dc1e26);
  box-shadow: 0 0 0 3px rgba(220, 30, 38, 0.14);
}
 
.home-ai-chat-form button {
  min-height: 35px;
  border: 0;
  border-radius: 10px;
  padding: 0 12px;
  background: linear-gradient(135deg, var(--primary, #dc1e26), var(--primary-strong, #b8141b));
  color: #ffffff;
  font-size: 9.9px;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  cursor: pointer;
}

/* ─── Keyframes ───────────────────────────────────────────────────────────── */
@keyframes fade-up {
  0%   { opacity: 0; transform: translateY(22px); }
  100% { opacity: 1; transform: translateY(0); }
}

@keyframes home-ai-halo-pulse {
  0%   { transform: scale(0.82); opacity: 0.58; }
  50%  { transform: scale(1.04); opacity: 0.95; }
  100% { transform: scale(0.82); opacity: 0.58; }
}

@keyframes home-ai-orbit-spin {
  0%   { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

@keyframes home-ai-orbit-spin-reverse {
  0%   { transform: rotate(55deg); }
  100% { transform: rotate(-305deg); }
}

@keyframes home-ai-core-shift {
  0%, 100% {
    transform: translateY(0);
    box-shadow: inset 0 0 0 1px rgba(241, 246, 253, 0.55), 0 0 0 6px rgba(220, 30, 38, 0.13);
  }
  50% {
    transform: translateY(-1px);
    box-shadow: inset 0 0 0 1px rgba(241, 246, 253, 0.65), 0 0 0 8px rgba(220, 30, 38, 0.18);
  }
}

@keyframes home-ai-typing {
  0%, 80%, 100% { transform: translateY(0); opacity: 0.5; }
  40%           { transform: translateY(-3px); opacity: 1; }
}

@keyframes booking-route-flow {
  0%, 100% { background-position: 0% 50%; }
  50%      { background-position: 100% 50%; }
}

@keyframes booking-bus-drive {
  0%, 100% { left: 70px; transform: translateY(-50%) scale(0.96); }
  50%      { left: calc(100% - 112px); transform: translateY(-50%) scale(1.04); }
}

@keyframes booking-step-pulse {
  0%, 100% {
    border-color: #dce4ef;
    transform: translateX(0);
  }
  35% {
    border-color: #8fcfc7;
    transform: translateX(5px);
  }
}

@keyframes assurance-float-one {
  0%, 100% { transform: translateY(0) rotate(-18deg); }
  50%      { transform: translateY(-12px) rotate(-6deg); }
}

@keyframes assurance-float-two {
  0%, 100% { transform: translateY(0) rotate(14deg); }
  50%      { transform: translateY(10px) rotate(28deg); }
}

@keyframes assurance-card-orbit-a {
  0%, 100% { transform: translate(0, 0); }
  35%      { transform: translate(10px, -8px); }
  70%      { transform: translate(-6px, 7px); }
}

@keyframes assurance-card-orbit-b {
  0%, 100% { transform: translate(0, 0); }
  35%      { transform: translate(-9px, 8px); }
  70%      { transform: translate(7px, -6px); }
}

@keyframes panel-in {
  0%   { opacity: 0; transform: translateY(24px); }
  100% { opacity: 1; transform: translateY(0); }
}

